mapper.select:
select t.content_id contentId, t.contract_id contractId, t.community_id communityId, t.template_id templateId, t.content content,
t.template_content templateContent, t.content_version contentVersion, t.status_cd statusCd,
t.create_time createTime, t.update_time updateTime
from contract_content t
where 1 = 1

    and t.content_id = #{contentId}


    and t.contract_id = #{contractId}


    and t.community_id = #{communityId}


    and t.status_cd = #{statusCd}


    limit #{page}, #{row}

select count(1) count
from contract_content t
where 1 = 1

    and t.content_id = #{contentId}


    and t.contract_id = #{contractId}


    and t.community_id = #{communityId}


    and t.status_cd = #{statusCd}
